import { createServer } from 'node:http';

const books = [
  { id: 1, title: 'Dune' },
  { id: 2, title: 'Neuromancer' },
];

function sendJson(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

async function readJsonBody(req) {
  let raw = '';
  for await (const chunk of req) raw += chunk;
  return raw ? JSON.parse(raw) : {};
}

const server = createServer(async (req, res) => {
  const { pathname, searchParams } = new URL(req.url, `http://${req.headers.host}`);

  if (req.method === 'GET' && pathname === '/api/books') {
    const q = searchParams.get('q')?.toLowerCase();
    const result = q ? books.filter((b) => b.title.toLowerCase().includes(q)) : books;
    return sendJson(res, 200, result);
  }

  if (req.method === 'POST' && pathname === '/api/books') {
    try {
      const body = await readJsonBody(req);
      if (typeof body.title !== 'string') return sendJson(res, 400, { error: 'title is required' });
      const book = { id: books.length + 1, title: body.title };
      books.push(book);
      return sendJson(res, 201, book);
    } catch {
      return sendJson(res, 400, { error: 'Body is not valid JSON' });
    }
  }

  sendJson(res, 404, { error: `No route for ${req.method} ${pathname}` });
});

server.listen(3000, () => console.log('API listening on http://localhost:3000'));
